import{_ as a,o as e,c as r,a3 as o}from"./chunks/framework.DotqndlA.js";const i="/ems_simulate/assets/iec61850-add.BMQDGqI_.png",l="/ems_simulate/assets/datamodel.DbpRX3Km.png",s="/ems_simulate/assets/reports.Ble3623S.png",d="/ems_simulate/assets/goose.DiSuKPeD.png",n="/ems_simulate/assets/iec61850-build.BWGiV7xf.png",S=JSON.parse('{"title":"IEC 61850 操作指南","description":"","frontmatter":{},"headers":[],"relativePath":"guide/protocols/iec61850/operation.md","filePath":"guide/protocols/iec61850/operation.md","lastUpdated":1786981506000}'),h={name:"guide/protocols/iec61850/operation.md"};function c(p,t,u,m,g,b){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="iec-61850-操作指南" tabindex="-1">IEC 61850 操作指南 <a class="header-anchor" href="#iec-61850-操作指南" aria-label="Permalink to &quot;IEC 61850 操作指南&quot;">​</a></h1><h2 id="一、前置条件" tabindex="-1">一、前置条件 <a class="header-anchor" href="#一、前置条件" aria-label="Permalink to &quot;一、前置条件&quot;">​</a></h2><ul><li>已安装并启动 EMS Simulate；</li><li><strong>服务端模拟</strong>：准备一个 ICD/SCD/CID 模型文件（可用&quot;建模工作台&quot;创建，或使用示例文件）；</li><li><strong>客户端模式</strong>：需要一台可访问的真实 IED（或本软件再模拟一台服务端）。</li></ul><h2 id="二、服务端模式-模拟-ied" tabindex="-1">二、服务端模式（模拟 IED） <a class="header-anchor" href="#二、服务端模式-模拟-ied" aria-label="Permalink to &quot;二、服务端模式（模拟 IED）&quot;">​</a></h2><p><strong>目标</strong>：导入 SCL 模型后模拟一个 IED，提供 MMS 读写、GOOSE、Reports、Files 服务。</p><h3 id="步骤-1-添加设备并导入模型" tabindex="-1">步骤 1：添加设备并导入模型 <a class="header-anchor" href="#步骤-1-添加设备并导入模型" aria-label="Permalink to &quot;步骤 1：添加设备并导入模型&quot;">​</a></h3><ol><li>点击&quot;<strong>添加设备</strong>&quot;；</li><li>协议选择 <strong>IEC 61850</strong>，连接方式选择 <strong>服务端（Server）</strong>；</li><li>选择 ICD / SCD / CID 文件上传，系统自动解析 IED 模型并生成测点（含 GOOSE 控制块、数据集）；</li><li>保存并&quot;<strong>开启设备</strong>&quot;。</li></ol><p><img src="'+i+'" alt=""></p><h3 id="步骤-2-查看数据模型" tabindex="-1">步骤 2：查看数据模型 <a class="header-anchor" href="#步骤-2-查看数据模型" aria-label="Permalink to &quot;步骤 2：查看数据模型&quot;">​</a></h3><p>设备详情中以树形结构展示 <strong>LD / LN / DO / DA</strong> 层级与 FC 功能约束，可展开查看每个测点的 MMS 类型；支持按节点类型筛选、搜索。</p><h3 id="步骤-3-mms-读写" tabindex="-1">步骤 3：MMS 读写 <a class="header-anchor" href="#步骤-3-mms-读写" aria-label="Permalink to &quot;步骤 3：MMS 读写&quot;">​</a></h3><ul><li>选中测点执行&quot;读取 / 写入&quot;，验证 MMS 报文交互；</li><li>支持批量读取、自动读取与变化追踪；</li><li>IEC 61850 客户端设备（模拟对端）也可直接读写本服务端。</li></ul><p><img src="'+l+'" alt=""></p><h3 id="步骤-4-goose-发布-订阅" tabindex="-1">步骤 4：GOOSE 发布 / 订阅 <a class="header-anchor" href="#步骤-4-goose-发布-订阅" aria-label="Permalink to &quot;步骤 4：GOOSE 发布 / 订阅&quot;">​</a></h3><ul><li><strong>发布</strong>：配置 GOOSE 控制块（GCB）与数据集，启动后周期/变位发送组播报文；</li><li><strong>订阅</strong>：添加接收器订阅对端 GOOSE，监视数据集成员值变化；</li><li><strong>抓包</strong>：选择真实网卡实时抓取 GOOSE 报文，解析 APPID、MAC、数据集成员值。</li></ul><blockquote><p>🖼️ 截图占位（待补充）：GOOSE 抓包界面</p></blockquote><h3 id="步骤-5-reports-报告" tabindex="-1">步骤 5：Reports 报告 <a class="header-anchor" href="#步骤-5-reports-报告" aria-label="Permalink to &quot;步骤 5：Reports 报告&quot;">​</a></h3><p>配置报告控制块（RCB）：</p><ul><li><strong>URCB（非缓存）</strong> / <strong>BRCB（缓存）</strong>；</li><li>配置数据集、触发条件（数据变化 dchg、品质变化 qchg、总召唤 GI）；</li><li>支持报告树形数据展示与数据集的批量读取。</li></ul><p><img src="'+s+'" alt=""></p><h3 id="步骤-6-files-文件服务" tabindex="-1">步骤 6：Files 文件服务 <a class="header-anchor" href="#步骤-6-files-文件服务" aria-label="Permalink to &quot;步骤 6：Files 文件服务&quot;">​</a></h3><p>通过 MMS Files 浏览设备文件目录、上传与下载文件（文件服务目录可在协议参数中配置）。</p><p><img src="'+d+'" alt=""></p><h2 id="三、客户端模式-连接真实-ied" tabindex="-1">三、客户端模式（连接真实 IED） <a class="header-anchor" href="#三、客户端模式-连接真实-ied" aria-label="Permalink to &quot;三、客户端模式（连接真实 IED）&quot;">​</a></h2><ol><li>添加设备时连接方式选择 <strong>客户端（Client）</strong>，填写目标 IP 与端口（MMS 默认 102）；</li><li>启动后客户端<strong>动态发现</strong> IED 数据模型并生成测点树（可配置模型发现超时）；</li><li>执行 MMS 读写、GOOSE 订阅、Reports 订阅与文件浏览。</li></ol><h2 id="四、建模工作台" tabindex="-1">四、建模工作台 <a class="header-anchor" href="#四、建模工作台" aria-label="Permalink to &quot;四、建模工作台&quot;">​</a></h2><p>基于 SCL 文件的工程化建模：</p><ol><li>新建工程（名称、编码、文件类型 ICD/CID/SCD、标准版本）；</li><li>配置 IED 信息（IED 名称、访问点、厂商、设备类型）与逻辑设备（LD）；</li><li>在模型树中编辑节点、添加逻辑节点、配置 DataSet 成员（支持 DO 整组/DA 精确选择）；</li><li>执行校验、保存版本并发布。</li></ol><p><img src="'+n+'" alt=""></p><h2 id="五、协议参数详解" tabindex="-1">五、协议参数详解 <a class="header-anchor" href="#五、协议参数详解" aria-label="Permalink to &quot;五、协议参数详解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td>连接超时</td><td>3000ms</td><td>建立 MMS 连接的超时时间</td></tr><tr><td>命令超时</td><td>3000ms</td><td>单条 MMS 服务等待响应的超时时间</td></tr><tr><td>模型发现超时</td><td>60s</td><td>客户端发现数据模型的超时时间</td></tr><tr><td>用户认证</td><td>关</td><td>启用 ACSE 认证（服务端校验客户端密码）</td></tr><tr><td>文件服务目录</td><td>空</td><td>向 MMS 客户端公开的文件目录</td></tr><tr><td>MMS 报文抓包</td><td>关</td><td>使用 Npcap/libpcap 抓取 MMS 报文</td></tr></tbody></table><h2 id="六、常见问题" tabindex="-1">六、常见问题 <a class="header-anchor" href="#六、常见问题" aria-label="Permalink to &quot;六、常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>排查建议</th></tr></thead><tbody><tr><td>客户端发现模型慢/超时</td><td>增大&quot;模型发现超时&quot;，确认网络可达</td></tr><tr><td>GOOSE 收不到</td><td>确认网卡选择正确、组播地址与 APPID 匹配</td></tr><tr><td>报告不触发</td><td>确认数据集已配置、触发条件（dchg/qchg/GI）正确</td></tr><tr><td>认证失败</td><td>确认服务端与客户端认证密码一致</td></tr><tr><td>SCL 校验报错</td><td>按校验结果修正模型后再导入</td></tr></tbody></table><blockquote><p>📄 报文如何解析见 <a href="./packet-view.html">IEC 61850 报文查看</a>。</p></blockquote>',34)])])}const _=a(h,[["render",c]]);export{S as __pageData,_ as default};
